s.append(sheet(9,'全量回归与联调测试结果',para(f'<strong>{r["passed"]} 组通过，{r["failed"]} 组失败。</strong>另含5个后端单元测试；视口覆盖390×844、360×740、430×932，中英文、日夜、在线和离线入口、后台PC及手机布局。')+para('全部写操作在独立SQLite测试库执行，测试完成后清理测试库。正式本地库未注入测试账号、视频、老师或520条批量数据。浏览器真实执行上传、审核、播放、CSV下载、套餐发布归档、记录提交与受理回看。')+f'<ol class="test-list">{results}</ol>'+para(f'浏览器API证据：{calls} 次响应，{routes} 个方法/路径组合。证据只记录方法、脱敏路径和状态码，不记录Cookie、密钥或正文。预期401/403/404及模拟503用于失败路径断言，不能简单把出现非200计为系统故障。')+para('有限测试不能证明绝对无缺陷。未覆盖公网、真实AI、实体手机、真实硬件、生产规模压力与真实支付。浏览器检查通过不等于用户视觉认可。')))
roadmap=[('P0 公开与多账号使用前','完善账号级本地隔离、访客迁移、记录读回、断网待同步队列与冲突处理；统一状态与时间字段','换账号不串档；断网重连可恢复；跨设备数据范围有明确验收用例'),('P0 正式部署前','数据库迁移版本、恢复演练、TLS与Cookie配置、生产服务器、部署配置和日志监控','重启升级与恢复可复现；无公开初始化或凭据暴露；不使用当前回环开发服务直接对外'),('P1 内容运营准备','真实授权内容、老师资料、媒体；服务器分页与检索；来源和授权信息管理','运营提供来源/授权/可收费与AI引用边界；内容发布、下架、检索与容量验证'),('P1 外部服务联调','AI供应商、模型与额度；设备品牌SDK、授权与指标样例；支付沙箱和会员权益模型','逐一测试成功、失败、超时、取消、撤权、支付幂等和退款，留真实证据'),('P2 持续运营','媒体迁移对象存储、异步任务、缓存、统一可观测性与规模评估','依据真实媒体体量和并发数据决定拆分，不提前声称支持高并发')]
s.append(sheet(10,'实施规划与验收顺序',para('以下为后续建设规划，不作为当前已完成功能。先解决数据归属、外部授权和部署基础，再接入真实服务；不设未经确认的上线日期。')+table(['阶段','工作内容','完成标准'],roadmap,[20,44,36])+h('需要业务方提供')+para('AI服务账号与允许使用的模型；设备品牌、SDK、供应商接口和合法测试设备；老师身份及授权资料；课程、音频、视频和内容使用范围；支付主体、商户配置与沙箱；部署环境、域名及运营责任人。密钥应通过服务端配置，不放入评审文件或前端源码。')+h('维护与发布流程')+para('需求与契约变更 → 修改同一项目源码 → 构建前检查 → 独立数据库全量回归 → 查看请求证据及截图 → 备份 → 更新说明和清单 → 验收后再部署。每次完成模块继续执行全量回归，失败先修复重跑。')+h('交付与证据入口')+table(['文件','用途'],[('05_后台与研发说明/后台管理使用手册.txt','运营实际操作步骤'),('06_验证与后续工作/本轮全量回归结果.json','当前批次、历史批次、逐项结果与构建哈希'),('06_验证与后续工作/前后端接口实测证据.json','浏览器API方法、脱敏路径与状态码'),('06_验证与后续工作/前后端接口契约对照表.json','APP与管理端接口字段和授权摘要'),('06_验证与后续工作/联调-老师需求受理回看.png','老师需求闭环浏览器截图'),('07_历史版本仅供追溯/前后端契约对齐前时间戳.zip','修改前源码与构建回退存档，不含运行数据库')],[61,39])+para('当前后台入口 http://127.0.0.1:8765/admin 。启动方式和数据库备份见使用手册。报告核验对象是本项目实际源码和构建产物，历史截图与旧报告不代替本轮证据。')))
css='''*{box-sizing:border-box}body{margin:0;background:#e8ece9;color:#1e2d26;font:15px/1.72 "Microsoft YaHei",sans-serif}.sheet{width:100%;max-width:1000px;margin:25px auto;padding:40px 48px;background:white;box-shadow:0 2px 15px #1836270c}.eyebrow{font-size:10px;letter-spacing:2px;color:#64766b;margin-bottom:16px}h1{font-size:27px;line-height:1.4;font-weight:600;color:#000;margin:0 0 22px}h2{font-size:17px;color:#000;margin:23px 0 9px;break-after:avoid}p{margin:0 0 12px;orphans:2;widows:2}.date{font-size:12px;color:#53655a;padding:5px 0 14px}table{border-collapse:collapse;width:100%;font-size:12px;line-height:1.65;margin:12px 0 17px;table-layout:fixed}thead{display:table-header-group}th,td{border:1px solid #d4ddd6;padding:9px 10px;text-align:left;vertical-align:middle;overflow-wrap:anywhere}th{color:#fff;background:#304f41;font-weight:500}tbody tr:nth-child(even){background:#f5f7f4}tr{break-inside:avoid}.flow{display:flex;gap:10px}.flow>div,.layer{flex:1;border:1px solid #c5d4c8;padding:12px;text-align:center;background:#f2f6f1;border-radius:3px}.flow small,.layer small{font-size:11px;color:#637466}.arrow{text-align:center;font-size:11px;padding:7px;color:#637466}.test-list{padding-left:20px;font-size:11px;line-height:1.5;columns:2;column-gap:33px;margin:16px 0}.test-list li{break-inside:avoid;padding:3px 0 5px}.test-list span{font-size:9px;color:#397451;margin-left:6px}.toolbar{max-width:1000px;margin:20px auto;text-align:right;font-size:12px}.toolbar button{background:#304f41;color:white;border:0;padding:10px 18px;border-radius:5px;cursor:pointer}a{color:#245e46}@page{size:A4;margin:14mm 13mm 17mm}@media print{body{background:white;font-size:14.5px;line-height:1.65}.sheet{max-width:none;margin:0;padding:0;box-shadow:none;break-after:page}.sheet:last-child{break-after:auto}.eyebrow{font-size:8px;margin-bottom:10px}h1{font-size:25px;margin-bottom:15px}h2{font-size:17px;margin:16px 0 7px}p{margin-bottom:9px}table{font-size:11.5px;line-height:1.55;margin:8px 0 12px}th,td{padding:7px 7px}.test-list{font-size:12px;line-height:1.55;column-gap:25px}.test-list li{padding:2px 0 4px}.test-list span{font-size:9px}.toolbar{display:none}.flow>div,.layer{padding:10px}.flow small,.layer small,.arrow{font-size:9px}.date{font-size:10px}}@media(max-width:650px){.sheet{margin:12px 0;padding:25px 18px}h1{font-size:23px}table{font-size:10px}th,td{padding:7px}.test-list{columns:1}.flow{flex-wrap:wrap}.flow>div{min-width:120px}}'''
